if(which==='inventory')$('#usePotion').onclick=()=>{if(inventory[2].qty>0&&health<100){health=Math.min(100,health+45);inventory[2].qty--;toast('The draught restores your vitality');updateBars()}else toast(inventory[2].qty?'You are already at full vitality':'No draughts remain')};}
function updateBars(){$('#healthBar').style.width=`${health}%`;$('#staminaBar').style.width=`${stamina}%`}
function interact(){if(paused||!started)return;const p=hero.group.position,n=npc.group.position,c=chest.position;const dn=Math.hypot(p.x-n.x,p.z-n.z),dc=Math.hypot(p.x-c.x,p.z-c.z);if(dn<3.3){if(questStage===0){setStage(1);toast('Elowen: “A blue light beneath the reeds… find the old shrine.”')}else if(questStage===1)toast('Elowen: “The river remembers what we have forgotten.”');else if(questStage===2){relic=false;setStage(3);health=100;toast('Elowen: “The river is quiet again. Hearthglen is in your debt.”')}else toast('Elowen: “The valley feels alive once more.”');saveGame();return}if(dc<3.2){if(questStage===1&&!opened){opened=true;relic=true;inventory.push({name:'River relic',icon:'✧',qty:1});setStage(2);chestTop.rotation.x=-1.05;chestTop.position.y=1.02;toast('You found the River Relic. Return it to Elowen.');saveGame()}else if(opened)toast('The reliquary is empty');else toast('The reliquary is sealed. Elowen may know more.');return}toast('There is nothing close enough to interact with')}
function attack(){if(paused||!started||attackTimer>0||stamina<12)return;attackTimer=.55;stamina-=12;const p=hero.group.position;let target=null,best=3.25;for(const w of wolves){if(!w.alive)continue;const d=Math.hypot(w.model.group.position.x-p.x,w.model.group.position.z-p.z);const dx=(w.model.group.position.x-p.x)/Math.max(d,.01),dz=(w.model.group.position.z-p.z)/Math.max(d,.01);const facing=new THREE.Vector2(Math.sin(hero.group.rotation.y),Math.cos(hero.group.rotation.y));if(d<best&&dx*facing.x+dz*facing.y>-.1){best=d;target=w}}if(target){target.hp--;const g=target.model.group;g.position.x+=Math.sin(hero.group.rotation.y)*.65;g.position.z+=Math.cos(hero.group.rotation.y)*.65;g.rotation.z=.16;if(target.hp<=0){target.alive=false;scene.remove(g);kills++;inventory[3].qty+=3;toast('The wolf falls. You collect 3 old copper.');if(kills>=3&&questStage===1)toast('The Whisperwood grows quiet.')}else toast('A clean strike!')}else toast('Your blade cuts through the air');updateBars()}
function jump(){if(paused||!started)return;if(Math.abs(jumpY)<.03){jumpV=5.5;stamina=Math.max(0,stamina-4)}}
function dodge(){if(paused||!started||stamina<18||dodgeTimer>0)return;dodgeTimer=.38;invuln=.65;stamina-=18;const d=hero.group.rotation.y;hero.group.position.x+=Math.sin(d)*1.45;hero.group.position.z+=Math.cos(d)*1.45;updateBars()}
